// Photograph manifest for the /photographs section.
// Frames are straight out of a Fujifilm X-M5 in one of four film simulations;
// `lqip` is a 20px JPEG data URI used as the blur-up placeholder.
//
// Generated from the design project's photos.js — see components/photography.

export type SimId =
  "all" | "classic-chrome" | "acros" | "nostalgic-neg" | "velvia";

export type Photo = {
  id: string;
  frame: string;
  src: string;
  lqip: string;
  ratio: number;
  vertical: boolean;
  natW: number;
  natH: number;
  sim: Exclude<SimId, "all">;
  place: string;
  city: string;
  kind: string;
  lens: string;
  focal: string;
  aperture: string;
  shutter: string;
  iso: number;
  date: string;
  title: string;
  body: string;
};

export type Sim = {
  id: SimId;
  name: string;
  short: string;
  accent: string;
  ink: string;
  paper: string;
  filter: string;
  grain: number;
  swatch: string;
  note?: string;
};

/** A photo laid out inside a justified row, with its resolved box. */
export type LaidOutPhoto = Photo & { w: number; h: number };

export type Row = {
  id: string;
  h: number;
  last?: boolean;
  items: LaidOutPhoto[];
};

